4826|    case ZSTD_greedy:
4827|    case ZSTD_lazy:
4828|    case ZSTD_lazy2:
4829|#if !defined(ZSTD_EXCLUDE_GREEDY_BLOCK_COMPRESSOR) \
4830| || !defined(ZSTD_EXCLUDE_LAZY_BLOCK_COMPRESSOR) \
