237|static size_t ZSTD_ldm_fillFastTables(ZSTD_matchState_t* ms,
238|                                      void const* end)
239|{
240|    const BYTE* const iend = (const BYTE*)end;
241|
242|    switch(ms->cParams.strategy)
243|    {
244|    case ZSTD_fast:
245|        ZSTD_fillHashTable(ms, iend, ZSTD_dtlm_fast, ZSTD_tfp_forCCtx);
246|        break;
247|
248|    case ZSTD_dfast:
249|#ifndef ZSTD_EXCLUDE_DFAST_BLOCK_COMPRESSOR
250|        ZSTD_fillDoubleHashTable(ms, iend, ZSTD_dtlm_fast, ZSTD_tfp_forCCtx);
251|#else
252|        assert(0); /* shouldn't be called: cparams should've been adjusted. */
253|#endif
254|        break;
255|
256|    case ZSTD_greedy:
257|    case ZSTD_lazy:
258|    case ZSTD_lazy2:
259|    case ZSTD_btlazy2:
260|    case ZSTD_btopt:
261|    case ZSTD_btultra:
262|    case ZSTD_btultra2:
263|        break;
264|    default:
265|        assert(0);  /* not possible : not a valid strategy id */
266|    }
267|
268|    return 0;
