1425|size_t ZSTD_compressBlock_btultra2(
1426|        ZSTD_matchState_t* ms, seqStore_t* seqStore, U32 rep[ZSTD_REP_NUM],
1427|        const void* src, size_t srcSize)
1428|{
1429|    U32 const curr = (U32)((const BYTE*)src - ms->window.base);
1430|    DEBUGLOG(5, "ZSTD_compressBlock_btultra2 (srcSize=%zu)", srcSize);
1431|
1432|    /* 2-passes strategy:
1433|     * this strategy makes a first pass over first block to collect statistics
1434|     * in order to seed next round's statistics with it.
1435|     * After 1st pass, function forgets history, and starts a new block.
1436|     * Consequently, this can only work if no data has been previously loaded in tables,
1437|     * aka, no dictionary, no prefix, no ldm preprocessing.
1438|     * The compression ratio gain is generally small (~0.5% on first block),
1439|    ** the cost is 2x cpu time on first block. */
1440|    assert(srcSize <= ZSTD_BLOCKSIZE_MAX);
1441|    if ( (ms->opt.litLengthSum==0)   /* first block */
1442|      && (seqStore->sequences == seqStore->sequencesStart)  /* no ldm */
1443|      && (ms->window.dictLimit == ms->window.lowLimit)   /* no dictionary */
1444|      && (curr == ms->window.dictLimit)    /* start of frame, nothing already loaded nor skipped */
1445|      && (srcSize > ZSTD_PREDEF_THRESHOLD) /* input large enough to not employ default stats */
1446|      ) {
1447|        ZSTD_initStats_ultra(ms, seqStore, rep, src, srcSize);
1448|    }
1449|
1450|    return ZSTD_compressBlock_opt2(ms, seqStore, rep, src, srcSize, ZSTD_noDict);
1451|}

