429|static void decompress(
430|    SharedState& state,
431|    std::shared_ptr<BufferWorkQueue> in,
432|    std::shared_ptr<BufferWorkQueue> out) {
433|  auto& errorHolder = state.errorHolder;
434|  auto guard = makeScopeGuard([&] { out->finish(); });
435|  // Initialize the DCtx
436|  auto ctx = state.dStreamPool->get();
437|  if (!errorHolder.check(ctx != nullptr, "Failed to allocate ZSTD_DStream")) {
438|    return;
439|  }
440|  {
441|    auto err = ZSTD_DCtx_reset(ctx.get(), ZSTD_reset_session_only);
442|    if (!errorHolder.check(!ZSTD_isError(err), ZSTD_getErrorName(err))) {
443|      return;
444|    }
445|  }
446|
447|  const size_t outSize = ZSTD_DStreamOutSize();
448|  Buffer inBuffer;
449|  size_t returnCode = 0;
450|  // Read a buffer in from the input queue
451|  while (in->pop(inBuffer) && !errorHolder.hasError()) {
452|    auto zstdInBuffer = makeZstdInBuffer(inBuffer);
453|    // Decompress the whole buffer and send it to the output queue
454|    while (!inBuffer.empty() && !errorHolder.hasError()) {
455|      // Allocate a buffer with at least outSize bytes.
456|      Buffer outBuffer(outSize);
457|      auto zstdOutBuffer = makeZstdOutBuffer(outBuffer);
458|      // Decompress
459|      returnCode =
460|          ZSTD_decompressStream(ctx.get(), &zstdOutBuffer, &zstdInBuffer);
461|      if (!errorHolder.check(
462|              !ZSTD_isError(returnCode), ZSTD_getErrorName(returnCode))) {
463|        return;
464|      }
465|      // Pass the buffer with the decompressed data to the output queue
466|      out->push(split(outBuffer, zstdOutBuffer));
467|      // Advance past the input we already read
468|      advance(inBuffer, zstdInBuffer);
469|      if (returnCode == 0) {
470|        // The frame is over, prepare to (maybe) start a new frame
471|        ZSTD_initDStream(ctx.get());
472|      }
473|    }
474|  }
475|  if (!errorHolder.check(returnCode <= 1, "Incomplete block")) {
476|    return;
477|  }
478|  // We've given ZSTD_decompressStream all of our data, but there may still
479|  // be data to read.
480|  while (returnCode == 1) {
481|    // Allocate a buffer with at least outSize bytes.
482|    Buffer outBuffer(outSize);
483|    auto zstdOutBuffer = makeZstdOutBuffer(outBuffer);
484|    // Pass in no input.
485|    ZSTD_inBuffer zstdInBuffer{nullptr, 0, 0};
486|    // Decompress
487|    returnCode =
488|        ZSTD_decompressStream(ctx.get(), &zstdOutBuffer, &zstdInBuffer);
489|    if (!errorHolder.check(
490|            !ZSTD_isError(returnCode), ZSTD_getErrorName(returnCode))) {
491|      return;
492|    }
493|    // Pass the buffer with the decompressed data to the output queue
494|    out->push(split(outBuffer, zstdOutBuffer));
495|  }
496|}

30|static void decompress(const char* fname, const ZSTD_DDict* ddict)
31|{
32|    size_t cSize;
33|    void* const cBuff = mallocAndLoadFile_orDie(fname, &cSize);
34|    /* Read the content size from the frame header. For simplicity we require
35|     * that it is always present. By default, zstd will write the content size
36|     * in the header when it is known. If you can't guarantee that the frame
37|     * content size is always written into the header, either use streaming
38|     * decompression, or ZSTD_decompressBound().
39|     */
40|    unsigned long long const rSize = ZSTD_getFrameContentSize(cBuff, cSize);
41|    CHECK(rSize != ZSTD_CONTENTSIZE_ERROR, "%s: not compressed by zstd!", fname);
42|    CHECK(rSize != ZSTD_CONTENTSIZE_UNKNOWN, "%s: original size unknown!", fname);
43|    void* const rBuff = malloc_orDie((size_t)rSize);
44|
45|    /* Check that the dictionary ID matches.
46|     * If a non-zstd dictionary is used, then both will be zero.
47|     * By default zstd always writes the dictionary ID into the frame.
48|     * Zstd will check if there is a dictionary ID mismatch as well.
49|     */
50|    unsigned const expectedDictID = ZSTD_getDictID_fromDDict(ddict);
51|    unsigned const actualDictID = ZSTD_getDictID_fromFrame(cBuff, cSize);
52|    CHECK(actualDictID == expectedDictID,
53|          "DictID mismatch: expected %u got %u",
54|          expectedDictID,
55|          actualDictID);
56|
57|    /* Decompress using the dictionary.
58|     * If you need to control the decompression parameters, then use the
59|     * advanced API: ZSTD_DCtx_setParameter(), ZSTD_DCtx_refDDict(), and
60|     * ZSTD_decompressDCtx().
61|     */
62|    ZSTD_DCtx* const dctx = ZSTD_createDCtx();
63|    CHECK(dctx != NULL, "ZSTD_createDCtx() failed!");
64|    size_t const dSize = ZSTD_decompress_usingDDict(dctx, rBuff, rSize, cBuff, cSize, ddict);
65|    CHECK_ZSTD(dSize);
66|    /* When zstd knows the content size, it will error if it doesn't match. */
67|    CHECK(dSize == rSize, "Impossible because zstd will check this condition!");
68|
69|    /* success */
70|    printf("%25s : %6u -> %7u \n", fname, (unsigned)cSize, (unsigned)rSize);
71|
72|    ZSTD_freeDCtx(dctx);
73|    free(rBuff);
74|    free(cBuff);
75|}

