833|size_t ZSTD_decompressionMargin(void const* src, size_t srcSize)
834|{
835|    size_t margin = 0;
836|    unsigned maxBlockSize = 0;
837|
838|    /* Iterate over each frame */
839|    while (srcSize > 0) {
840|        ZSTD_frameSizeInfo const frameSizeInfo = ZSTD_findFrameSizeInfo(src, srcSize);
841|        size_t const compressedSize = frameSizeInfo.compressedSize;
842|        unsigned long long const decompressedBound = frameSizeInfo.decompressedBound;
843|        ZSTD_frameHeader zfh;
844|
845|        FORWARD_IF_ERROR(ZSTD_getFrameHeader(&zfh, src, srcSize), "");
846|        if (ZSTD_isError(compressedSize) || decompressedBound == ZSTD_CONTENTSIZE_ERROR)
847|            return ERROR(corruption_detected);
848|
849|        if (zfh.frameType == ZSTD_frame) {
850|            /* Add the frame header to our margin */
851|            margin += zfh.headerSize;
852|            /* Add the checksum to our margin */
853|            margin += zfh.checksumFlag ? 4 : 0;
854|            /* Add 3 bytes per block */
855|            margin += 3 * frameSizeInfo.nbBlocks;
856|
857|            /* Compute the max block size */
858|            maxBlockSize = MAX(maxBlockSize, zfh.blockSizeMax);
859|        } else {
860|            assert(zfh.frameType == ZSTD_skippableFrame);
861|            /* Add the entire skippable frame size to our margin. */
862|            margin += compressedSize;
863|        }
864|
865|        assert(srcSize >= compressedSize);
866|        src = (const BYTE*)src + compressedSize;
867|        srcSize -= compressedSize;
868|    }
869|
870|    /* Add the max block size back to the margin. */
871|    margin += maxBlockSize;
872|
873|    return margin;
874|}

