16|static void ZSTD_fillDoubleHashTableForCDict(ZSTD_matchState_t* ms,
17|                              void const* end, ZSTD_dictTableLoadMethod_e dtlm)
18|{
19|    const ZSTD_compressionParameters* const cParams = &ms->cParams;
20|    U32* const hashLarge = ms->hashTable;
21|    U32  const hBitsL = cParams->hashLog + ZSTD_SHORT_CACHE_TAG_BITS;
22|    U32  const mls = cParams->minMatch;
23|    U32* const hashSmall = ms->chainTable;
24|    U32  const hBitsS = cParams->chainLog + ZSTD_SHORT_CACHE_TAG_BITS;
25|    const BYTE* const base = ms->window.base;
26|    const BYTE* ip = base + ms->nextToUpdate;
27|    const BYTE* const iend = ((const BYTE*)end) - HASH_READ_SIZE;
28|    const U32 fastHashFillStep = 3;
29|
30|    /* Always insert every fastHashFillStep position into the hash tables.
31|     * Insert the other positions into the large hash table if their entry
32|     * is empty.
33|     */
34|    for (; ip + fastHashFillStep - 1 <= iend; ip += fastHashFillStep) {
35|        U32 const curr = (U32)(ip - base);
36|        U32 i;
37|        for (i = 0; i < fastHashFillStep; ++i) {
38|            size_t const smHashAndTag = ZSTD_hashPtr(ip + i, hBitsS, mls);
39|            size_t const lgHashAndTag = ZSTD_hashPtr(ip + i, hBitsL, 8);
40|            if (i == 0) {
41|                ZSTD_writeTaggedIndex(hashSmall, smHashAndTag, curr + i);
42|            }
43|            if (i == 0 || hashLarge[lgHashAndTag >> ZSTD_SHORT_CACHE_TAG_BITS] == 0) {
44|                ZSTD_writeTaggedIndex(hashLarge, lgHashAndTag, curr + i);
45|            }
46|            /* Only load extra positions for ZSTD_dtlm_full */
47|            if (dtlm == ZSTD_dtlm_fast)
48|                break;
49|    }   }
