27|static void
28|ZSTD_updateDUBT(ZSTD_matchState_t* ms,
29|                const BYTE* ip, const BYTE* iend,
30|                U32 mls)
31|{
32|    const ZSTD_compressionParameters* const cParams = &ms->cParams;
33|    U32* const hashTable = ms->hashTable;
34|    U32  const hashLog = cParams->hashLog;
35|
36|    U32* const bt = ms->chainTable;
37|    U32  const btLog  = cParams->chainLog - 1;
38|    U32  const btMask = (1 << btLog) - 1;
39|
40|    const BYTE* const base = ms->window.base;
41|    U32 const target = (U32)(ip - base);
42|    U32 idx = ms->nextToUpdate;
43|
44|    if (idx != target)
45|        DEBUGLOG(7, "ZSTD_updateDUBT, from %u to %u (dictLimit:%u)",
46|                    idx, target, ms->window.dictLimit);
47|    assert(ip + 8 <= iend);   /* condition for ZSTD_hashPtr */
48|    (void)iend;
49|
50|    assert(idx >= ms->window.dictLimit);   /* condition for valid base+idx */
51|    for ( ; idx < target ; idx++) {
52|        size_t const h  = ZSTD_hashPtr(base + idx, hashLog, mls);   /* assumption : ip + 8 <= iend */
53|        U32    const matchIndex = hashTable[h];
54|
55|        U32*   const nextCandidatePtr = bt + 2*(idx&btMask);
56|        U32*   const sortMarkPtr  = nextCandidatePtr + 1;
57|
58|        DEBUGLOG(8, "ZSTD_updateDUBT: insert %u", idx);
59|        hashTable[h] = idx;   /* Update Hash Table */
60|        *nextCandidatePtr = matchIndex;   /* update BT like a chain */
61|        *sortMarkPtr = ZSTD_DUBT_UNSORTED_MARK;
62|    }
63|    ms->nextToUpdate = target;
